-- サービス名を mcp-portfolio から MCP Shelf に変える。slug（portfolio）と URL はそのまま
UPDATE `servers` SET `name` = 'MCP Shelf', `summary` = 'このサイト自身。掲載している MCP サーバーの一覧と詳細を、Claude から読めるようにする', `description` = 'このサイト自体もリモート MCP サーバーです。Claude に URL を渡すと、掲載しているサーバーの一覧やツール定義を読めます。Streamable HTTP のステートレス構成で、読み取り専用のツールを 2 つ提供します。', `config` = '{"mcpServers":{"mcp-shelf":{"type":"http","url":"{{MCP_URL}}"}}}' WHERE `slug` = 'portfolio';
